@namespace sv_cbde4718cd11478a8d8d4cde97807df5.Components.Pages.Board

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..." value="@SearchTerm"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

