@namespace sv_cbde4718cd11478a8d8d4cde97807df5.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <div class="board-loading">Loading tasks...</div>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar TotalCount="allTasks.Count"
                   ToDoCount="todoTasks.Count"
                   InProgressCount="inProgressTasks.Count"
                   DoneCount="doneTasks.Count"
                   OverdueCount="overdueTasks.Count" />

    <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do" Status="To Do"
                      Tasks="filteredTodo"
                      ShowMoveLeft="false" ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn ColumnName="In Progress" Status="In Progress"
                      Tasks="filteredInProgress"
                      ShowMoveLeft="true" ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn ColumnName="Done" Status="Done"
                      Tasks="filteredDone"
                      ShowMoveLeft="true" ShowMoveRight="false"
                      OnMoveTask="HandleMoveTask"
                      OnTaskCreated="HandleTaskCreated" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    private List<TaskItem> filteredTodo => ApplyFilter(todoTasks);
    private List<TaskItem> filteredInProgress => ApplyFilter(inProgressTasks);
    private List<TaskItem> filteredDone => ApplyFilter(doneTasks);

    private List<TaskItem> ApplyFilter(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchTerm))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task HandleMoveTask((TaskItem Task, string Direction) moveInfo)
    {
        var currentIndex = Array.IndexOf(Statuses, moveInfo.Task.Status);
        var newIndex = moveInfo.Direction == "left" ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= Statuses.Length)
            return;

        var newStatus = Statuses[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(moveInfo.Task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == moveInfo.Task.Id);
            if (index >= 0)
            {
                allTasks[index] = moveInfo.Task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated((string Title, string Assignee, string Priority, DateTime DueDate, string Status) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            allTasks.Add(newTask with { Status = data.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}
"}

